'use strict';
colors.Pearl='#d9c79a';
bondDescriptions.Pearl='Level 2: +1 tide shell per pick';
creatureTemperaments.Pearl={trait:'Cautious · watches the tide',clues:['It peers out from beneath a shell, watching the water.','It edges closer between waves, curious about your footprints.'],actions:[['still','Sit quietly'],['wave','Wave with the tide'],['reach','Reach towards it']],best:['still','wave'],good:'It scuttles closer, leaving little trails in the sand.',bad:'It ducks beneath its shell. Wait for the next quiet wave.'};
const coastTypes=['coastMarker','coastNest'];
const coastNear=nearest;nearest=function(){let best=coastNear(),d=best?Math.hypot(best.x-player.x,best.y-player.y):43;for(const o of map.objects.filter(o=>coastTypes.includes(o.type))){const n=Math.hypot(o.x-player.x,o.y-player.y);if(n<d){best=o;d=n;}}return best;};
function coastChapter(){return CoastCore.chapters[state.coast.stage];}
function coastQuestCard(){const q=state.coast,c=coastChapter();return `<article class="story-feature">${gameIcon(q.stage===6?'check':'map')}<small>TIDEGLASS COAST · ${Math.min(6,q.stage+1)} / 6</small><h3>${c?c[0]:'A harbour open to the tide'}</h3><p>${c?c[1]:'Pearl has a home, the harbour holds firm and the wider coast is open.'}</p>${q.stage===1?`<span>${q.markers.length} / 3 driftwood markers found</span>`:q.stage===2?`<span>${Math.min(12,Math.max(0,state.frontier.gathered.shells-q.shellStart))} / 12 fresh shells</span>`:''}</article>`;}
function coastGuide(){panel('The harbour reopens',coastQuestCard()+'<div class="actions"><button data-ui="close">Back to the trail</button><button data-front="requests">Regional requests</button></div>','Kai’s survey','coast');}
function kaiDialog(){const q=state.coast;const lines=['“The old harbour’s taken a beating from the tide. Will you help me get it seaworthy again?”','“Three driftwood markers show where the harbour wall used to stand. Find them along the shore.”','“Fresh shells tell me the tide’s brought good material. Collect twelve, then come find me.”','“Forty timber and twelve shells should mend the wall. Meet me at the harbour.”','“Something’s been watching from the tide pools south of here. See if it will come out.”','“You found our little tide-watcher! Let’s get this harbour open again.”','“Listen to the boats creak against the new wall. You’ve opened the whole coast.”'];const action=q.stage===0?'talk':q.stage===2?'shell':q.stage===5?'finish':null;panel('Kai',`<p>${lines[q.stage]}</p>${coastQuestCard()}<div class="actions">${action?`<button data-coast="${action}" ${q.stage===2&&state.frontier.gathered.shells-q.shellStart<12?'disabled':''}>${q.stage===0?'I’ll help':q.stage===2?'Show the fresh shells':'Celebrate · collect rewards'}</button>`:''}<button data-front="requests">Requests</button><button data-ui="close">See you soon</button></div>`,'Harbour keeper','coast');}
function coastObjectMenu(o){const q=state.coast;let title='The coast',body='',action='';
 if(o.type==='coastMarker'){title='A driftwood tide marker';body=q.markers.includes(o.marker)?'Already logged in Kai’s notes.':'A sun-bleached post, half buried in sand. Worth reporting back.';if(q.stage===1&&!q.markers.includes(o.marker))action=`<button data-coast="marker" data-marker="${o.marker}">Log this marker</button>`;}
 if(o.type==='landmark'){title='The old harbour wall';body=q.stage<3?'Kai has a plan for this place. Visit the camp to the south.':q.stage===3?'Repair the wall with fresh timber and shells.':q.stage<6?'The wall is sound. Follow Kai’s plan to bring the harbour back.':'A working harbour. Shell gathering here now yields an extra piece.';if(q.stage===3)action=`${state.frontier.projects.harbour?'<p>Materials already paid for.</p>':`<div class="ingredient-row">${chip('wood',40,state.wood)}${chip('shells',12,state.shells)}</div>`}<button data-coast="repair" ${!state.frontier.projects.harbour&&(state.wood<40||state.shells<12)?'disabled':''}>Repair the wall</button>`;}
 if(o.type==='coastNest'){if(q.stage>=4&&!state.team.includes('Pearl')){encounter={name:'Pearl',trust:0};encounterDialog();return;}title='The quiet tide pools';body=state.team.includes('Pearl')?'Pearl rests in a sun-warmed pool between the rocks. Always close, always watching the tide.':'Tiny trails circle a still tide pool. Perhaps an open harbour will bring its owner out.';}
 panel(title,`<p>${body}</p>${action}<div class="actions"><button data-coast="guide">Kai’s plan</button><button data-ui="close">Keep exploring</button></div>`,'Tideglass Coast','coast');
}
const coastInteract=interact;interact=function(){if(!dialog&&!activity){const o=nearest();if(SaveStore.status().blocked){saveMenu();return;}if(map.id==='coast'&&o?.name==='Kai'){kaiDialog();return;}if(map.id==='coast'&&(coastTypes.includes(o?.type)||o?.type==='landmark')){faceTarget(o);coastObjectMenu(o);return;}}coastInteract();};
app.addEventListener('click',e=>{const b=e.target.closest('[data-coast]');if(!b||b.disabled)return;const a=b.dataset.coast;if(a==='guide'){coastGuide();return;}if(SaveStore.status().blocked){saveMenu();return;}const o=nearest(),allowed=['talk','shell','finish'].includes(a)?map.id==='coast'&&o?.name==='Kai':map.id==='coast'&&({marker:'coastMarker',repair:'landmark'}[a]===o?.type);if(!allowed||(a==='marker'&&Number(b.dataset.marker)!==o.marker))return;if(CoastCore.act(state,a,Number(b.dataset.marker))){finish(a==='finish'?'The harbour reopens! +100 coins · +3 trail marks · +6 shells':a==='marker'?`${state.coast.markers.length} / 3 markers found`:a==='repair'?'Harbour wall repaired! Something is still watching the tide pools.':'Kai’s plan updated.');}if(o?.name==='Kai')kaiDialog();else coastObjectMenu(o);});
const coastTick=tickActivities;tickActivities=function(dt){const people=map.npcs;if(map.id==='tessa')map.npcs=[];coastTick(dt);if(map.id==='tessa')map.npcs=people;if(CoastCore.act(state,'friend')){state.jobs.Pearl='fish';finish('Pearl joined the harbour camp. Tell Kai the good news!');}};
const coastComplete=completeActivity;completeActivity=function(){if(activity?.o.type==='shell'&&state.life.active==='Pearl'&&MossSystems.level(state,'Pearl')>=2)state.shells++;coastComplete();};
const coastAdventure=adventureMenu;adventureMenu=function(){coastAdventure();if(taskTab==='story'){const b=document.createElement('button');b.dataset.coast='guide';b.textContent=state.coast.stage===6?'Tideglass Coast · Complete':'Kai’s coast · '+coastChapter()[0];document.querySelector('.dialog .panel-tabs').after(b);}};
const coastMap=mapPanel;mapPanel=function(){coastMap();const b=document.createElement('button');b.dataset.coast='guide';b.textContent='Tideglass Coast · Kai’s plan';document.querySelector('.dialog').append(b);};
const coastObject=object;object=function(o){if(map.id==='coast'){if(o.type==='coastMarker'){const found=state.coast.markers.includes(o.marker);rr(o.x-3,o.y-14,6,14,'#a89264');rr(o.x-7,o.y-17,14,6,found?'#c7b26a':'#8f7a4f');text(found?'✓':'?',o.x,o.y-12,found?'#eef3c0':'#f6e6ac',9);return;}if(o.type==='coastNest'){rr(o.x-13,o.y-3,26,7,'#b7ab8a');rr(o.x-9,o.y-6,18,5,'#dcd0ac');if(state.coast.stage>=4&&!state.team.includes('Pearl'))text('?',o.x,o.y-10,'#fff0b8',12);return;}}coastObject(o);};
// Old saves may stand where the new markers or nest now block a path.
if(map.id==='coast'&&blocked(map,player.x,player.y)){player.x=23*T+16;player.y=2*T+16;follower.x=player.x-24;follower.y=player.y;save();}
